describe('File Upload Progress Bar', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display progress bar for each file during upload', () => {
    // Intercept the upload API call
    cy.intercept('POST', '/api/files/upload').as('fileUpload');

    // Select a file from the file input
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Verify file name is displayed
    cy.get('[data-testid="file-name-display"]').should('contain', 'sample.pdf');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload API call
    cy.wait('@fileUpload');

    // Verify progress bar is visible and shows progress
    cy.get('[data-testid="progress-bar"]').should('be.visible');
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'style', 'width: 10%;');

    // Verify progress text is updated
    cy.get('[data-testid="progress-text"]').should('contain', '0%');

    // Verify upload success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');

    // Verify progress bar is hidden after completion
    cy.get('[data-testid="progress-bar"]').should('not.exist');
  });

  it('should handle multiple file uploads with individual progress bars', () => {
    // Intercept upload API calls for multiple files
    cy.intercept('POST', '/api/files/upload').as('fileUpload1');
    cy.intercept('POST', '/api/files/upload').as('fileUpload2');

    // Select first file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document1.docx', { force: true });
    cy.get('[data-testid="upload-button"]').click();

    // Wait for first file upload
    cy.wait('@fileUpload1');

    // Verify first progress bar is visible
    cy.get('[data-testid="progress-bar-1"]').should('be.visible');
    cy.get('[data-testid="progress-text-1"]').should('contain', '10%');

    // Select second file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/image.png', { force: true });
    cy.get('[data-testid="upload-button"]').click();

    // Wait for second file upload
    cy.wait('@fileUpload2');

    // Verify second progress bar is visible
    cy.get('[data-testid="progress-bar-2"]').should('be.visible');
    cy.get('[data-testid="progress-text-2"]').should('contain', '50%');

    // Verify both files have success messages
    cy.get('[data-testid="success-message-1"]').should('be.visible');
    cy.get('[data-testid="success-message-2"]').should('be.visible');

    // Verify both progress bars are hidden
    cy.get('[data-testid="progress-bar-1"]').should('not.exist');
    cy.get('[data-testid="progress-bar-2"]').should('not.exist');
  });
});
